async function arrRender(kind){if(arrRenderBusy||!arrangement)return null;await arrStopPlayback();arrRenderBusy=true;const revision=arrRevision;$('arrGrid').inert=true;$('arrInspector').inert=true;$('arrProgress').hidden=false;$('arrCancel').hidden=false;$('arrPlay').disabled=true;for(const id of ['arrExportVideo','arrExportAudio','arrTrack','arrImport','arrUndo','arrRedo','arrName','arrBPM','arrSnap'])$(id).disabled=true;try{await arrSave();let job=await nativeBeginArrangementRender(JSON.parse(JSON.stringify(arrangement)),kind);if(!job.ID)return null;while(job.State==='rendering'){$('arrProgress').value=job.Progress;$('arrRenderStatus').textContent=(kind==='preview'?'Preparing preview':'Exporting')+' · '+Math.round(job.Progress*100)+'%';arrNotice($('arrRenderStatus').textContent);await new Promise(resolve=>setTimeout(resolve,300));job=await nativeArrangementRenderStatus();}if(job.State!=='ready')throw new Error(job.Error||'Render cancelled.');$('arrProgress').value=1;$('arrRenderStatus').textContent=kind==='preview'?'Preview ready.':'Saved: '+job.Path;arrNotice($('arrRenderStatus').textContent);if(kind==='preview'){arrPreviewID=job.ID;arrPreviewRevision=revision;const v=$('arrPreview'),loaded=waitVideo(v,'loadedmetadata');v.src=arrURL('render',job.ID);v.hidden=false;v.load();await loaded;}return job;}catch(e){$('arrRenderStatus').textContent=errorText(e);arrNotice(errorText(e));return null;}finally{arrRenderBusy=false;$('arrGrid').inert=false;$('arrInspector').inert=false;$('arrCancel').hidden=true;$('arrPlay').disabled=false;for(const id of ['arrExportVideo','arrExportAudio','arrTrack','arrImport','arrName','arrBPM','arrSnap'])$(id).disabled=false;renderArrangement();}}
