async function arrStopPlayback(reset=false){arrPlaying=false;clearTimeout(arrPoll);$('arrPreview').pause();$('arrPlay').textContent='▶ Play';await nativeStopArrangementPreview();if(reset)arrCursor=0;arrUpdateCursor();}
