$('arrPlay').onclick=()=>arrPlaying?arrStopPlayback():arrStartPlayback();$('arrStop').onclick=()=>arrStopPlayback(true);
document.addEventListener('keydown',e=>{if(currentTab!=='arrange'||e.target.closest('input,textarea,select,button,dialog')||arrRenderBusy)return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)$('arrPlay').click();}if(e.key==='Delete'){e.preventDefault();$('arrDelete').click();}if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('arrRedo'):$('arrUndo')).click();}});

